const schedule = require('node-schedule');

module.exports = function(RED) {
    function KumvaSchedulerNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        let job = null;

        function startJob() {
            if (job) job.cancel();
            
            job = schedule.scheduleJob(config.cron, function() {
                const msg = {
                    payload: "scheduled",
                    campaignId: `sched_${Date.now()}`,
                    timestamp: new Date().toISOString()
                };
                node.send(msg);
                node.status({ fill: "green", shape: "dot", text: "Triggered" });
            });
        }

        if (config.enabled) startJob();

        node.on('close', function() {
            if (job) job.cancel();
        });
    }

    RED.nodes.registerType("kumva-scheduler", KumvaSchedulerNode);
};